NOISE <- -1L
dbscan <- function(neighborhoods, min_pts) {
    core <- lengths(neighborhoods) >= min_pts
    labels <- rep(-2L, length(neighborhoods))
    queue <- integer(sum(lengths(neighborhoods)))
    cluster <- 0L
    for (point in seq_along(neighborhoods)) {
        if (labels[point] != -2L) next
        if (!core[point]) {
            labels[point] <- NOISE
            next
        }
        labels[point] <- cluster
        tail <- length(neighborhoods[[point]])
        queue[seq_len(tail)] <- neighborhoods[[point]]
        head <- 1L
        while (head <= tail) {
            other <- queue[head]
            head <- head + 1L
            if (labels[other] == NOISE) labels[other] <- cluster else if (labels[other] == -2L) {
                labels[other] <- cluster
                if (core[other]) {
                    neighbors <- neighborhoods[[other]]
                    queue[seq.int(tail + 1L, tail + length(neighbors))] <- neighbors
                    tail <- tail + length(neighbors)
                }
            }
        }
        cluster <- cluster + 1L
    }
    list(labels = labels, core = core)
}

squared_distance <- function(a, b) (a$x - b$x) * (a$x - b$x) + (a$y - b$y) * (a$y - b$y)
cell_key <- function(gx, gy) paste(gx, gy, sep = ":")
grid_index <- function(points, eps) {
    cells <- list()
    for (i in seq_along(points)) {
        point <- points[[i]]
        key <- cell_key(point$x %/% eps, point$y %/% eps)
        cells[[key]] <- c(cells[[key]], i)
    }
    list(points = points, eps = eps, cells = cells)
}
neighborhood <- function(grid, index) {
    point <- grid$points[[index]]
    column <- point$x %/% grid$eps
    row <- point$y %/% grid$eps
    neighbors <- integer()
    candidates <- 0L
    for (gy in seq.int(row - 1, row + 1)) for (gx in seq.int(column - 1, column + 1)) {
        for (other in grid$cells[[cell_key(gx, gy)]]) {
            candidates <- candidates + 1L
            if (squared_distance(
                point,
                grid$points[[other]]
            ) <= grid$eps * grid$eps) neighbors <- c(neighbors, other)
        }
    }
    list(neighbors = neighbors, candidates = candidates)
}
busiest_cell <- function(grid) {
    coordinates <- lapply(strsplit(names(grid$cells), ":", fixed = TRUE), as.numeric)
    sizes <- lengths(grid$cells)
    index <- order(
        -sizes,
        vapply(coordinates, function(cell) cell[2L], 0),
        vapply(coordinates, function(cell) cell[1L], 0)
    )[1L]
    c(coordinates[[index]], sizes[index])
}
brute_force_counts <- function(points, eps) vapply(
    points,
    function(point) sum(vapply(points, function(other) squared_distance(point, other) <= eps * eps, FALSE)),
    0L
)

INF <- 9007199254740991
core_distances <- function(points, neighborhoods, min_pts) vapply(seq_along(points), function(index) {
    neighbors <- neighborhoods[[index]]
    if (length(neighbors) < min_pts) INF else sort(vapply(
        neighbors,
        function(other) squared_distance(points[[index]], points[[other]]),
        0
    ))[min_pts]
}, 0)
optics_ordering <- function(points, neighborhoods, core) {
    n <- length(points)
    reach <- rep(INF, n)
    predecessor <- integer(n)
    processed <- logical(n)
    ordering <- integer()
    for (start in seq_len(n)) {
        if (processed[start]) next
        seeds <- logical(n)
        seeds[start] <- TRUE
        while (any(seeds)) {
            choices <- which(seeds)
            current <- choices[which.min(reach[choices])]
            seeds[current] <- FALSE
            processed[current] <- TRUE
            ordering <- c(ordering, current)
            if (core[current] == INF) next
            for (other in neighborhoods[[current]]) {
                if (processed[other]) next
                distance <- max(core[current], squared_distance(points[[current]], points[[other]]))
                if (distance < reach[other]) {
                    reach[other] <- distance
                    predecessor[other] <- current
                    seeds[other] <- TRUE
                }
            }
        }
    }
    list(ordering = ordering, reach = reach, predecessor = predecessor)
}

gcd <- function(a, b) {
    while (b != 0) {
        remainder <- a %% b
        a <- b
        b <- remainder
    }
    a
}
fraction_text <- function(a, b) {
    divisor <- gcd(abs(a), b)
    paste0(sprintf("%.0f", a %/% divisor), "/", sprintf("%.0f", b %/% divisor))
}
root_text <- function(value) sprintf("%.3f", sqrt(value))
ari_text <- function(a, b) {
    value <- sprintf("%.4f", a / b)
    if (value == "-0.0000") value <- "0.0000"
    paste(fraction_text(a, b), value)
}
framed <- function(rows, width) {
    border <- paste0("+", strrep("-", width), "+")
    c(border, paste0("|", rows, "|"), border)
}
write_lines <- function(name, lines) {
    dir.create("output", showWarnings = FALSE)
    writeLines(lines, file.path("output", name), useBytes = TRUE)
}
